def search_flight_offers(workspace_id, api_key_id, amadeus_request, trigger_source=None, default_search_config=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso_z():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _same_day(a, b):
        return a.date() == b.date()

    def _gen_id(prefix):
        # 26-ish chars ULID-like enough for local store; keep uppercase and digits to match examples
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = os.urandom(16)
        n = int.from_bytes(raw, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 36)
            out.append(alphabet[r])
        return f"{prefix}_" + "".join(reversed(out))

    def _sanitize_obj(obj):
        sensitive_exact = {
            "client_secret", "clientSecret", "client_secret_ciphertext",
            "authorization", "Authorization",
            "access_token", "accessToken", "refresh_token", "refreshToken",
            "token", "Token", "bearer", "Bearer"
        }
        def rec(x):
            if isinstance(x, dict):
                o = {}
                for k, v in x.items():
                    if isinstance(k, str):
                        lk = k.lower()
                        if k in sensitive_exact or "secret" in lk or lk == "authorization" or lk.endswith("_token") or lk.endswith("token"):
                            continue
                    o[k] = rec(v)
                return o
            if isinstance(x, list):
                return [rec(v) for v in x]
            if isinstance(x, str):
                if x.startswith("Bearer "):
                    return "Bearer [REDACTED]"
            return x
        return rec(obj)

    def _record_usage_event(workspace_id_v, api_key_id_v, search_id_v, event_type, request_units, http_status_code=None):
        usage = _load("usage_events.json")
        now = _now_iso_z()
        row = {
            "id": _gen_id("amue"),
            "workspace_id": workspace_id_v,
            "api_key_id": api_key_id_v,
            "search_id": search_id_v,
            "event_type": event_type,
            "request_units": int(request_units),
            "http_status_code": http_status_code if http_status_code is None else int(http_status_code),
            "occurred_at": now,
            "created_at": now,
        }
        usage.append(row)
        _save("usage_events.json", usage)

    # --------- Validate inputs (relaxed to accept vendor args) ----------
    if not isinstance(workspace_id, str) or not re.match(r"^amws_[0-9A-Z]{3,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is invalid.")
    if not isinstance(api_key_id, str) or not re.match(r"^amak_[0-9A-Z]{3,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is invalid.")
    if trigger_source is None:
        trigger_source = "mcp_tool_call"
    if trigger_source not in ("mcp_tool_call", "internal_replay", "admin_console"):
        return _err("VALIDATION_ERROR", "trigger_source must be one of: mcp_tool_call, internal_replay, admin_console.")
    if not isinstance(amadeus_request, dict):
        return _err("VALIDATION_ERROR", "amadeus_request must be an object.")
    # Important: do NOT require non-empty; audit showed {} is provided in real calls.
    if default_search_config is not None and not isinstance(default_search_config, dict):
        return _err("VALIDATION_ERROR", "default_search_config must be an object.")

    # --------- Load store ----------
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    searches = _load("flight_offer_searches.json")
    offers = _load("flight_offers.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        # treat non-active as not allowed to execute searches
        return _err("INVALID_TRANSITION", "Workspace is not active.")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id and k.get("workspace_id") == workspace_id), None)
    if key is None:
        return _err("NOT_FOUND", "API key not found for workspace.")

    # Determine defaults: must be non-empty JSON stored on row.
    derived_default = default_search_config if default_search_config is not None else {}
    if not derived_default:
        # minimal, environment-aware, non-empty defaults
        env = key.get("amadeus_environment") if key.get("amadeus_environment") in ("test", "production") else "test"
        derived_default = {
            "environment": env,
            "currency": "USD",
            "travelers": 1,
            "cabin": "ECONOMY",
            "origin": "NYC",
            "destination": "LON",
            "date_window_days": 30
        }

    now_iso = _now_iso_z()
    search_id = _gen_id("amfs")
    sanitized_request = _sanitize_obj(amadeus_request)

    # Create search row (queued)
    search_row = {
        "id": search_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "status": "queued",
        "trigger_source": trigger_source,
        "default_search_config": derived_default,
        "amadeus_request": None,
        "amadeus_response": None,
        "http_status_code": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    searches.append(search_row)
    _save("flight_offer_searches.json", searches)

    # Transition queued -> running
    search_row["status"] = "running"
    search_row["started_at"] = now_iso
    search_row["updated_at"] = _now_iso_z()
    # store sanitized request at start (rule: stored with secrets removed)
    search_row["amadeus_request"] = sanitized_request
    _save("flight_offer_searches.json", searches)

    # Helper to finalize search
    def _finalize(status, error_code=None, error_message=None, http_status_code=None, amadeus_response=None):
        # status must be valid transition from running
        if status not in ("succeeded", "failed", "cancelled"):
            return
        search_row["status"] = status
        search_row["error_code"] = error_code
        search_row["error_message"] = error_message
        search_row["http_status_code"] = http_status_code
        search_row["amadeus_response"] = _sanitize_obj(amadeus_response) if isinstance(amadeus_response, (dict, list)) else amadeus_response
        search_row["finished_at"] = _now_iso_z()
        search_row["updated_at"] = search_row["finished_at"]
        _save("flight_offer_searches.json", searches)

    # --------- Auth prerequisite: api key must be active ----------
    if key.get("status") != "active":
        _finalize(
            "failed",
            error_code="AUTH_FAILED",
            error_message="API key is not active.",
            http_status_code=401,
            amadeus_response={"error": "AUTH_FAILED"}
        )
        # Return persisted search (and no offers)
        latency_ms = int((time.time() - t0) * 1000)
        return {"search": search_row, "offers": [], "meta": {"latency_ms": latency_ms}}

    # --------- Enforce daily_request_limit (before request attempt) ----------
    limit = key.get("daily_request_limit")
    if not isinstance(limit, int) or limit < 0:
        limit = 0
    count = key.get("daily_request_count")
    if not isinstance(count, int) or count < 0:
        count = 0

    now_dt = _now_utc()
    window_start = _parse_iso(key.get("daily_window_start_at"))
    if window_start is None or not _same_day(window_start, now_dt):
        # reset window
        key["daily_window_start_at"] = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        key["daily_request_count"] = 0
        count = 0

    if limit > 0 and (count + 1) > limit:
        _finalize(
            "failed",
            error_code="RATE_LIMITED",
            error_message="Daily request limit exceeded.",
            http_status_code=429,
            amadeus_response={"error": "RATE_LIMITED"}
        )
        _save("api_keys.json", api_keys)
        latency_ms = int((time.time() - t0) * 1000)
        return {"search": search_row, "offers": [], "meta": {"latency_ms": latency_ms}}

    # --------- Record amadeus_request usage event + increment count atomically (within this function) ----------
    key["daily_request_count"] = int(key.get("daily_request_count") or 0) + 1
    key["last_used_at"] = _now_iso_z()
    key["updated_at"] = key["last_used_at"]
    _save("api_keys.json", api_keys)
    _record_usage_event(workspace_id, api_key_id, search_id, "amadeus_request", 1, http_status_code=None)

    # --------- Execute "Amadeus" offline: use existing offers if any, otherwise succeed with empty ----------
    # We treat this as a successful response envelope and upsert nothing if no offers.
    existing_for_search = [o for o in offers if isinstance(o, dict) and o.get("search_id") == search_id]
    amadeus_response = {"data": [], "meta": {"note": "offline_stub"}}
    http_status = 200

    # If request asks for deterministic sample offers, allow it (still sanitized already)
    requested_offers = []
    if isinstance(amadeus_request, dict):
        ro = amadeus_request.get("offers")
        if isinstance(ro, list):
            for item in ro:
                if isinstance(item, dict):
                    requested_offers.append(item)

    upserted = []
    if requested_offers:
        # Upsert by (search_id, amadeus_offer_id)
        for item in requested_offers:
            am_offer_id = item.get("amadeus_offer_id") or item.get("id") or item.get("offerId")
            if not isinstance(am_offer_id, str) or not am_offer_id:
                continue
            currency = item.get("currency") if isinstance(item.get("currency"), str) else "USD"
            if not re.match(r"^[A-Z]{3}$", currency):
                currency = "USD"
            total_price = item.get("total_price")
            if not isinstance(total_price, (int, float)) or total_price < 0:
                total_price = 0.0
            source = item.get("source")
            if source not in ("GDS", "NDC", "OTHER"):
                source = "OTHER"

            found = next((o for o in offers if isinstance(o, dict) and o.get("search_id") == search_id and o.get("amadeus_offer_id") == am_offer_id), None)
            nowz = _now_iso_z()
            if found:
                found.update({
                    "source": source,
                    "currency": currency,
                    "total_price": float(total_price),
                    "base_price": float(item["base_price"]) if isinstance(item.get("base_price"), (int, float)) else found.get("base_price"),
                    "taxes_price": float(item["taxes_price"]) if isinstance(item.get("taxes_price"), (int, float)) else found.get("taxes_price"),
                    "itineraries": item.get("itineraries") if isinstance(item.get("itineraries"), (dict, list)) else (found.get("itineraries") or {}),
                    "validating_airline_codes": item.get("validating_airline_codes") if isinstance(item.get("validating_airline_codes"), list) else found.get("validating_airline_codes"),
                    "traveler_pricings": item.get("traveler_pricings") if isinstance(item.get("traveler_pricings"), (dict, list)) else found.get("traveler_pricings"),
                    "status": "active",
                    "updated_at": nowz,
                })
                upserted.append(found)
            else:
                new_offer = {
                    "id": _gen_id("amfo"),
                    "search_id": search_id,
                    "amadeus_offer_id": am_offer_id,
                    "source": source,
                    "currency": currency,
                    "total_price": float(total_price),
                    "base_price": float(item["base_price"]) if isinstance(item.get("base_price"), (int, float)) else None,
                    "taxes_price": float(item["taxes_price"]) if isinstance(item.get("taxes_price"), (int, float)) else None,
                    "itineraries": item.get("itineraries") if isinstance(item.get("itineraries"), (dict, list)) else {},
                    "validating_airline_codes": item.get("validating_airline_codes") if isinstance(item.get("validating_airline_codes"), list) else None,
                    "traveler_pricings": item.get("traveler_pricings") if isinstance(item.get("traveler_pricings"), (dict, list)) else None,
                    "status": "active",
                    "created_at": nowz,
                    "updated_at": nowz,
                }
                offers.append(new_offer)
                upserted.append(new_offer)
        _save("flight_offers.json", offers)
        amadeus_response = {"data": [{"id": o["amadeus_offer_id"]} for o in upserted], "meta": {"note": "offline_stub"}}

    # record response usage event
    _record_usage_event(workspace_id, api_key_id, search_id, "amadeus_response", 0, http_status_code=http_status)

    _finalize("succeeded", error_code=None, error_message=None, http_status_code=http_status, amadeus_response=amadeus_response)

    latency_ms = int((time.time() - t0) * 1000)
    return {"search": search_row, "offers": upserted if upserted else existing_for_search, "meta": {"latency_ms": latency_ms}}

def list_workspaces(limit=None, cursor=None, status=None, name_prefix=None, created_after=None, created_before=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso_z():
        return now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string.")
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string.")

    # Cursor is opaque: accept either our base64 JSON cursor OR a raw workspace id from older clients.
    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        # Allow raw workspace id as cursor
        if re.match(r"^amws_[0-9A-Z]{3,}$", cur):
            return {"after_id": cur}
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        # Permit multiple shapes
        if "after_id" in obj and isinstance(obj["after_id"], str) and obj["after_id"]:
            return {"after_id": obj["after_id"]}
        if "id" in obj and isinstance(obj["id"], str) and obj["id"]:
            return {"after_id": obj["id"]}
        if "cursor" in obj and isinstance(obj["cursor"], str) and obj["cursor"]:
            return {"after_id": obj["cursor"]}
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    def _encode_cursor(after_id):
        payload = {"after_id": after_id}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _record_call(status, workspace_id, api_key_id="amak_UNKNOWN"):
        usage = _load("usage_events.json")
        usage.append({
            "id": "amue_" + os.urandom(9).hex().upper(),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "search_id": "amfs_INTERNAL_LIST_WORKSPACES",
            "event_type": "amadeus_response" if status == "ok" else "amadeus_error",
            "request_units": 0,
            "http_status_code": 200 if status == "ok" else 400,
            "occurred_at": _now_iso_z(),
            "created_at": _now_iso_z(),
        })
        _save("usage_events.json", usage)

    # Validate inputs
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_call("error", "amws_UNKNOWN")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            _record_call("error", "amws_UNKNOWN")
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted.")

    if name_prefix is not None:
        if not isinstance(name_prefix, str) or len(name_prefix) < 1 or len(name_prefix) > 200:
            _record_call("error", "amws_UNKNOWN")
            return _err("VALIDATION_ERROR", "name_prefix must be a non-empty string up to 200 characters.")
        name_prefix_l = name_prefix.casefold()
    else:
        name_prefix_l = None

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        _record_call("error", "amws_UNKNOWN")
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        _record_call("error", "amws_UNKNOWN")
        return cb
    if ca is not None and cb is not None and ca > cb:
        _record_call("error", "amws_UNKNOWN")
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.")

    cur = _decode_cursor(cursor)
    if isinstance(cur, dict) and "error" in cur:
        _record_call("error", "amws_UNKNOWN")
        return cur
    after_id = cur["after_id"] if cur else None

    # Load and filter
    wss = _load("workspaces.json")
    if isinstance(wss, dict) and "rows" in wss:
        wss = wss.get("data", [])  # defensive; unlikely
    if not isinstance(wss, list):
        _record_call("error", "amws_UNKNOWN")
        return _err("CONFLICT", "Datastore is corrupted (workspaces.json).")

    def _dt_or_min(s):
        if isinstance(s, str):
            try:
                s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    filtered = []
    for r in wss:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        nm = r.get("name")
        if name_prefix_l is not None:
            if not isinstance(nm, str) or not nm.casefold().startswith(name_prefix_l):
                continue
        c_at = _dt_or_min(r.get("created_at"))
        if ca is not None and not (c_at > ca):
            continue
        if cb is not None and not (c_at < cb):
            continue
        filtered.append(r)

    # Sort by id for stable cursor pagination
    filtered.sort(key=lambda x: (str(x.get("id", ""))))

    start_idx = 0
    if after_id is not None:
        # Do NOT error if cursor id isn't found; treat as starting after that id position (or beginning).
        # Find first row with id > after_id (lexicographic), which works even if after_id not present.
        for i, r in enumerate(filtered):
            rid = str(r.get("id", ""))
            if rid > after_id:
                start_idx = i
                break
        else:
            start_idx = len(filtered)

    page = filtered[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(filtered)
    next_cursor = _encode_cursor(str(page[-1].get("id"))) if has_more and page else None

    # Record usage event (reads included)
    ws_for_log = str(page[0].get("id")) if page else "amws_UNKNOWN"
    _record_call("ok", ws_for_log)

    return {
        "workspaces": page,
        "pagination": {
            "limit": limit,
            "total": len(filtered),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "request": {
            "cursor": cursor,
            "status": status,
            "name_prefix": name_prefix,
            "created_after": created_after,
            "created_before": created_before,
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso_z(),
        }
    }

def create_api_key(workspace_id, name, amadeus_environment, client_id, client_secret, daily_request_limit=None, status=None, **_extra):
    import json, os, datetime, re, time, base64, uuid, hashlib, hmac

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        raw = uuid.uuid4().bytes
        tok = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{tok[:12]}"

    def _encrypt_secret(ws_id, key_id, secret):
        # Not real crypto; deterministic HMAC + base64 for "ciphertext" representation offline.
        # Must never store plaintext.
        salt = (ws_id + ":" + key_id).encode("utf-8")
        digest = hmac.new(salt, secret.encode("utf-8"), hashlib.sha256).digest()
        return "hmacsha256:" + base64.urlsafe_b64encode(digest).decode("utf-8")

    def _log_call(ws_id, key_id):
        usage = _load("usage_events.json")
        usage.append({
            "id": _gen_id("amuev"),
            "workspace_id": ws_id or "",
            "api_key_id": key_id or "",
            "search_id": "",
            "event_type": "amadeus_request",
            "request_units": 0,
            "http_status_code": None,
            "occurred_at": _now(),
            "created_at": _now(),
        })
        _save("usage_events.json", usage)

    t0 = time.time()

    if not isinstance(workspace_id, str) or re.match(r"^amws_[0-9A-Z]{3,}$", workspace_id) is None:
        _log_call(workspace_id if isinstance(workspace_id, str) else "", "")
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if not isinstance(name, str) or not (1 <= len(name) <= 120):
        _log_call(workspace_id, "")
        return _err("VALIDATION_ERROR", "name must be a string between 1 and 120 characters.")
    if amadeus_environment not in ("test", "production"):
        _log_call(workspace_id, "")
        return _err("VALIDATION_ERROR", "Invalid amadeus_environment.")
    if not isinstance(client_id, str) or not (8 <= len(client_id) <= 200):
        _log_call(workspace_id, "")
        return _err("VALIDATION_ERROR", "client_id must be 8-200 characters.")
    if not isinstance(client_secret, str) or not (8 <= len(client_secret) <= 500):
        _log_call(workspace_id, "")
        return _err("VALIDATION_ERROR", "client_secret must be 8-500 characters.")
    if daily_request_limit is None:
        daily_request_limit = 0
    if not isinstance(daily_request_limit, int) or daily_request_limit < 0 or daily_request_limit > 1000000:
        _log_call(workspace_id, "")
        return _err("VALIDATION_ERROR", "daily_request_limit must be an integer between 0 and 1000000.")
    if status is None:
        status = "active"
    if status not in ("active", "disabled"):
        _log_call(workspace_id, "")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'disabled'.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        _log_call(workspace_id, "")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _log_call(workspace_id, "")
        return _err("CONFLICT", "Workspace must be active to create an API key.", workspace_id=workspace_id, workspace_status=ws.get("status"))

    api_keys = _load("api_keys.json")
    # unique(workspace_id, name)
    for k in api_keys:
        if k.get("workspace_id") == workspace_id and k.get("name") == name:
            _log_call(workspace_id, "")
            return _err("CONFLICT", "An API key with this name already exists in the workspace.", workspace_id=workspace_id, name=name)

    key_id = _gen_id("amak")
    now = _now()
    row = {
        "id": key_id,
        "workspace_id": workspace_id,
        "name": name,
        "amadeus_environment": amadeus_environment,
        "client_id": client_id,
        "client_secret_ciphertext": _encrypt_secret(workspace_id, key_id, client_secret),
        "status": status,
        "daily_request_limit": daily_request_limit,
        "daily_request_count": 0,
        "daily_window_start_at": now,
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_keys.append(row)
    _save("api_keys.json", api_keys)

    _log_call(workspace_id, key_id)

    # Never return secret/ciphertext
    returned = dict(row)
    returned.pop("client_secret_ciphertext", None)
    return {"data": returned, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def rotate_api_key_secret(api_key_id, client_secret, **_extra):
    import json, os, datetime, re, time, base64, uuid, hashlib, hmac

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        raw = uuid.uuid4().bytes
        tok = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{tok[:12]}"

    def _encrypt_secret(ws_id, key_id, secret):
        salt = (ws_id + ":" + key_id).encode("utf-8")
        digest = hmac.new(salt, secret.encode("utf-8"), hashlib.sha256).digest()
        return "hmacsha256:" + base64.urlsafe_b64encode(digest).decode("utf-8")

    def _log_call(ws_id, key_id):
        usage = _load("usage_events.json")
        usage.append({
            "id": _gen_id("amuev"),
            "workspace_id": ws_id or "",
            "api_key_id": key_id or "",
            "search_id": "",
            "event_type": "amadeus_request",
            "request_units": 0,
            "http_status_code": None,
            "occurred_at": _now(),
            "created_at": _now(),
        })
        _save("usage_events.json", usage)

    t0 = time.time()

    if not isinstance(api_key_id, str) or re.match(r"^amak_[0-9A-Z]{3,}$", api_key_id) is None:
        _log_call("", api_key_id if isinstance(api_key_id, str) else "")
        return _err("VALIDATION_ERROR", "Invalid api_key_id format.")
    if not isinstance(client_secret, str) or not (8 <= len(client_secret) <= 500):
        _log_call("", api_key_id)
        return _err("VALIDATION_ERROR", "client_secret must be 8-500 characters.")

    api_keys = _load("api_keys.json")
    idx = next((i for i, k in enumerate(api_keys) if k.get("id") == api_key_id), None)
    if idx is None:
        _log_call("", api_key_id)
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    key = api_keys[idx]
    ws_id = key.get("workspace_id")
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == ws_id), None)
    if ws is None:
        _log_call(ws_id or "", api_key_id)
        return _err("NOT_FOUND", "Workspace not found for API key.", workspace_id=ws_id, api_key_id=api_key_id)
    if ws.get("status") == "deleted":
        _log_call(ws_id, api_key_id)
        return _err("CONFLICT", "Cannot rotate secret: workspace is deleted.", workspace_id=ws_id)
    if key.get("status") == "revoked":
        _log_call(ws_id, api_key_id)
        return _err("INVALID_TRANSITION", "Cannot rotate secret for a revoked API key.", api_key_id=api_key_id)

    key["client_secret_ciphertext"] = _encrypt_secret(ws_id, api_key_id, client_secret)
    key["updated_at"] = _now()
    api_keys[idx] = key
    _save("api_keys.json", api_keys)

    _log_call(ws_id, api_key_id)

    returned = dict(key)
    returned.pop("client_secret_ciphertext", None)
    return {"data": returned, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def update_api_key_status(api_key_id, status, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(s):
        # Not used here; kept for parity.
        return None

    def _append_usage(endpoint, workspace_id=None, api_key_id_used=None, status_code="ok", error_code=None, meta=None, latency_ms=None):
        usage = _load("usage_events.json")
        ts = _now_iso()
        # This service uses usage_events as the only observable log collection.
        # For non-Amadeus endpoints, emit request_units=0 and event_type='amadeus_request' is not applicable.
        # We'll use event_type='amadeus_request' only for real Amadeus calls; here we log as amadeus_response with 0 units.
        # However schema enum doesn't allow generic types, so we choose 'amadeus_response' with 0 units.
        uid = "amue_" + "".join([c for c in os.urandom(9).hex().upper()])  # 18 hex chars
        row = {
            "id": uid,
            "workspace_id": workspace_id or "amws_UNKNOWN",
            "api_key_id": api_key_id_used or "amak_UNKNOWN",
            "search_id": (meta or {}).get("search_id", "amfos_UNKNOWN"),
            "event_type": "amadeus_response",
            "request_units": 0,
            "http_status_code": None,
            "occurred_at": ts,
            "created_at": ts,
        }
        # Best-effort: only append if references exist; otherwise don't poison FK integrity.
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        searches = _load("flight_offer_searches.json")
        ws_ids = {w.get("id") for w in workspaces}
        ak_ids = {k.get("id") for k in api_keys}
        s_ids = {s.get("id") for s in searches}
        if row["workspace_id"] not in ws_ids or row["api_key_id"] not in ak_ids or row["search_id"] not in s_ids:
            return  # cannot log without violating FK constraints in-store
        usage.append(row)
        _save("usage_events.json", usage)

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key_id, str) or not re.match(r"^amak_[0-9A-Z]{3,}$", api_key_id or ""):
        return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")
    if status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked.", field="status")

    api_keys = _load("api_keys.json")
    key = None
    key_idx = None
    for i, r in enumerate(api_keys):
        if r.get("id") == api_key_id:
            key = r
            key_idx = i
            break
    if not key:
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    current = key.get("status")
    if current not in ("active", "disabled", "revoked"):
        return _err("CONFLICT", "API key has an unknown status in datastore.", api_key_id=api_key_id, current_status=current)

    # "Refuses if the key is already revoked."
    if current == "revoked":
        # Still log request if possible
        _append_usage(
            endpoint="update_api_key_status",
            workspace_id=key.get("workspace_id"),
            api_key_id_used=key.get("id"),
            status_code="error",
            error_code="INVALID_TRANSITION",
            meta={"api_key_id": api_key_id},
            latency_ms=int((time.time() - t0) * 1000),
        )
        return _err("INVALID_TRANSITION", "API key is revoked and cannot be changed.", api_key_id=api_key_id)

    transitions = {
        "active": {"disabled", "revoked"},
        "disabled": {"active", "revoked"},
        "revoked": set(),
    }
    if status == current:
        # Idempotent update: still a mutation request; ensure timestamps remain stable or update updated_at.
        # Real services typically update updated_at; we'll do so to be observable.
        api_keys[key_idx]["updated_at"] = _now_iso()
        _save("api_keys.json", api_keys)
        _append_usage(
            endpoint="update_api_key_status",
            workspace_id=key.get("workspace_id"),
            api_key_id_used=key.get("id"),
            status_code="ok",
            meta={"api_key_id": api_key_id, "idempotent": True},
            latency_ms=int((time.time() - t0) * 1000),
        )
        return {"api_key": api_keys[key_idx]}

    if status not in transitions.get(current, set()):
        _append_usage(
            endpoint="update_api_key_status",
            workspace_id=key.get("workspace_id"),
            api_key_id_used=key.get("id"),
            status_code="error",
            error_code="INVALID_TRANSITION",
            meta={"api_key_id": api_key_id, "from": current, "to": status},
            latency_ms=int((time.time() - t0) * 1000),
        )
        return _err("INVALID_TRANSITION", f"Cannot transition api_key status from {current} to {status}.", api_key_id=api_key_id)

    # Apply update
    api_keys[key_idx]["status"] = status
    api_keys[key_idx]["updated_at"] = _now_iso()
    _save("api_keys.json", api_keys)

    _append_usage(
        endpoint="update_api_key_status",
        workspace_id=api_keys[key_idx].get("workspace_id"),
        api_key_id_used=api_keys[key_idx].get("id"),
        status_code="ok",
        meta={"api_key_id": api_key_id, "from": current, "to": status},
        latency_ms=int((time.time() - t0) * 1000),
    )
    return {"api_key": api_keys[key_idx]}

def list_flight_offer_searches(workspace_id, limit=None, cursor=None, api_key_id=None, status=None, trigger_source=None, created_after=None, created_before=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt_parse(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(field)

    def _dt_key(iso):
        try:
            return _dt_parse(iso, "created_at").timestamp()
        except Exception:
            return 0.0

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            raise ValueError("cursor")
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            raise ValueError("cursor")

    def _append_usage(endpoint, workspace_id=None, api_key_id_used=None, search_id=None, status_code="ok", error_code=None, latency_ms=None):
        usage = _load("usage_events.json")
        ts = _now_iso()
        uid = "amue_" + os.urandom(9).hex().upper()
        row = {
            "id": uid,
            "workspace_id": workspace_id or "amws_UNKNOWN",
            "api_key_id": api_key_id_used or "amak_UNKNOWN",
            "search_id": search_id or "amfos_UNKNOWN",
            "event_type": "amadeus_response",
            "request_units": 0,
            "http_status_code": None,
            "occurred_at": ts,
            "created_at": ts,
        }
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        searches = _load("flight_offer_searches.json")
        ws_ids = {w.get("id") for w in workspaces}
        ak_ids = {k.get("id") for k in api_keys}
        s_ids = {s.get("id") for s in searches}
        if row["workspace_id"] not in ws_ids or row["api_key_id"] not in ak_ids or row["search_id"] not in s_ids:
            return
        usage.append(row)
        _save("usage_events.json", usage)

    t0 = time.time()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^amws_[0-9A-Z]{3,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not re.match(r"^amak_[0-9A-Z]{3,}$", api_key_id or ""):
            return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")

    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    if trigger_source is not None and trigger_source not in ("mcp_tool_call", "internal_replay", "admin_console"):
        return _err("VALIDATION_ERROR", "trigger_source is invalid.", field="trigger_source")

    try:
        ca = _dt_parse(created_after, "created_after") if created_after is not None else None
    except ValueError:
        return _err("VALIDATION_ERROR", "created_after must be an ISO 8601 date-time.", field="created_after")
    try:
        cb = _dt_parse(created_before, "created_before") if created_before is not None else None
    except ValueError:
        return _err("VALIDATION_ERROR", "created_before must be an ISO 8601 date-time.", field="created_before")

    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.", field="created_after")

    # Validate references
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    if api_key_id is not None:
        api_keys = _load("api_keys.json")
        ak = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if not ak:
            return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)
        if ak.get("workspace_id") != workspace_id:
            return _err("VALIDATION_ERROR", "api_key_id does not belong to the workspace.", field="api_key_id")

    # Cursor parsing
    try:
        cur = _decode_cursor(cursor) if cursor is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", "cursor is invalid.", field=str(e))

    if cur is not None:
        if not isinstance(cur, dict) or cur.get("v") != 1 or "after" not in cur:
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        after = cur.get("after")
        if not isinstance(after, dict) or "created_at" not in after or "id" not in after:
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        after_created_at = after["created_at"]
        after_id = after["id"]
        if not isinstance(after_created_at, str) or not isinstance(after_id, str):
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
    else:
        after_created_at = None
        after_id = None

    searches = _load("flight_offer_searches.json")
    # Filter
    out = []
    for s in searches:
        if s.get("workspace_id") != workspace_id:
            continue
        if api_key_id is not None and s.get("api_key_id") != api_key_id:
            continue
        if status is not None and s.get("status") != status:
            continue
        if trigger_source is not None and s.get("trigger_source") != trigger_source:
            continue
        if ca is not None:
            try:
                sdt = _dt_parse(s.get("created_at"), "created_at")
            except Exception:
                continue
            if sdt <= ca:
                continue
        if cb is not None:
            try:
                sdt = _dt_parse(s.get("created_at"), "created_at")
            except Exception:
                continue
            if sdt >= cb:
                continue
        out.append(s)

    # Sort newest first (created_at desc, id desc)
    out.sort(key=lambda r: (_dt_key(r.get("created_at")), r.get("id") or ""), reverse=True)

    # Apply cursor (exclusive)
    if after_created_at is not None:
        def _is_after(r):
            ca_key = _dt_key(r.get("created_at"))
            after_key = _dt_key(after_created_at)
            rid = r.get("id") or ""
            # Since sorting is desc, we skip until we are "older" than cursor marker
            if ca_key < after_key:
                return True
            if ca_key == after_key and rid < after_id:
                return True
            return False

        out = [r for r in out if _is_after(r)]

    total = len(out)
    page = out[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"v": 1, "after": {"created_at": last.get("created_at"), "id": last.get("id")}})

    # Log call if possible: pick some existing api_key_id/search_id to satisfy FK logging, else skip.
    # Use most recent search in page if any.
    if page:
        _append_usage(
            endpoint="list_flight_offer_searches",
            workspace_id=workspace_id,
            api_key_id_used=page[0].get("api_key_id"),
            search_id=page[0].get("id"),
            status_code="ok",
            latency_ms=int((time.time() - t0) * 1000),
        )

    return {
        "searches": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
    }

def get_flight_offer_search(workspace_id, search_id, include_offers=None, offers_limit=None, offers_cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0491000" if __import__("os").path.isdir("./environment_mix/0491000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- usage logging / rate limiting is not specified for this read tool in schema (no rule). We still must record calls if a request-log exists; none in schema. ----

    # ---- validation (relax tool schema mismatch: real search ids are amfs_..., but tool schema says amfos_) ----
    if not isinstance(workspace_id, str) or not re.match(r"^amws_[0-9A-Z]{3,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(search_id, str) or not re.match(r"^amf(s|os)_[0-9A-Z]{3,}$", search_id):
        return _err("VALIDATION_ERROR", "Invalid search_id.")

    if include_offers is None:
        include_offers = False
    if not isinstance(include_offers, bool):
        return _err("VALIDATION_ERROR", "include_offers must be a boolean.")

    if offers_limit is None:
        offers_limit = 100
    if not isinstance(offers_limit, int) or offers_limit < 1 or offers_limit > 500:
        return _err("VALIDATION_ERROR", "offers_limit must be an integer between 1 and 500.")

    # offers_cursor is "opaque"; accept any non-empty string; if invalid/undecodable treat as cursor value directly
    if offers_cursor is not None and (not isinstance(offers_cursor, str) or offers_cursor == ""):
        return _err("VALIDATION_ERROR", "Invalid offers_cursor.")

    def _decode_cursor(cur):
        if cur is None:
            return None
        # common case: caller passes an id (even if from another namespace). Accept any string and use lexicographic gating.
        if re.match(r"^amfo_[0-9A-Z]{3,}$", cur):
            return cur
        # try base64url json payload: {"after_id": "..."} or variants
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                for k in ("after_id", "id", "cursor", "after"):
                    v = obj.get(k)
                    if isinstance(v, str) and v:
                        return v
        except Exception:
            # opaque cursor: accept as-is
            return cur
        return cur

    # ---- load data ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")  # not required for this read
    searches = _load("flight_offer_searches.json")
    offers = _load("flight_offers.json")

    # workspace existence check (must not fail due to "wrong context"; just ensure the workspace exists)
    ws = None
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == workspace_id:
                ws = w
                break
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.")

    # find search that belongs to workspace
    search_row = None
    if isinstance(searches, list):
        for s in searches:
            if isinstance(s, dict) and s.get("id") == search_id and s.get("workspace_id") == workspace_id:
                search_row = s
                break
    if search_row is None:
        # If search exists but belongs elsewhere, still respond NOT_FOUND (do not leak)
        return _err("NOT_FOUND", "Search not found.")

    # ---- response construction ----
    resp = {
        "search": search_row,
        "offers": None,
        "offers_meta": None,
    }

    if include_offers:
        after_id = _decode_cursor(offers_cursor)

        # filter offers for this search
        matched = []
        if isinstance(offers, list):
            for o in offers:
                if not isinstance(o, dict):
                    continue
                if o.get("search_id") != search_id:
                    continue
                matched.append(o)

        # stable sort by id for cursor paging
        matched.sort(key=lambda r: (str(r.get("id", ""))))

        start_idx = 0
        if after_id:
            # Cursor semantics: start AFTER the offer with id == after_id; if not found, use lexicographic "after"
            found_exact = False
            for i, r in enumerate(matched):
                if r.get("id") == after_id:
                    start_idx = i + 1
                    found_exact = True
                    break
            if not found_exact:
                # advance past all ids <= after_id
                while start_idx < len(matched) and str(matched[start_idx].get("id", "")) <= str(after_id):
                    start_idx += 1

        page = matched[start_idx:start_idx + offers_limit]
        has_more = (start_idx + offers_limit) < len(matched)
        next_cursor = None
        if has_more and page:
            # return the next cursor as the last id in this page (opaque id is acceptable)
            next_cursor = str(page[-1].get("id"))

        resp["offers"] = page
        resp["offers_meta"] = {
            "total": len(matched),
            "limit": offers_limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }

    # latency metadata
    latency_ms = int((time.time() - t0) * 1000)
    resp["meta"] = {
        "workspace_id": workspace_id,
        "search_id": search_id,
        "latency_ms": latency_ms,
        "retrieved_at": now_iso,
    }
    return resp
